{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';

const port = Number(process.env.PORT || 8080);
const databasePath = process.env.DB_PATH || './workboard.sqlite';
const database = new DatabaseSync(databasePath);
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
  )
  ;
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
  )
`);
const projectColumns = database.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}

const indexHtml = await readFile(new URL('./index.html', import.meta.url));

function sendJson(response, status, value) {
  response.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) body += chunk;
  return JSON.parse(body);
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, `http://${request.headers.host || 'localhost'}`);

  if (request.method === 'GET' && url.pathname === '/health') {
    sendJson(response, 200, { status: 'ok' });
    return;
  }

  if (request.method === 'GET' && url.pathname === '/api/projects') {
    const projects = database.prepare(`SELECT p.id, p.name, p.archived,
      COUNT(t.id) AS totalCount, COALESCE(SUM(t.completed), 0) AS completedCount
      FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
      GROUP BY p.id ORDER BY p.id`).all().map((project) => ({
        ...project, id: Number(project.id), archived: Boolean(project.archived),
        totalCount: Number(project.totalCount), completedCount: Number(project.completedCount),
      }));
    sendJson(response, 200, projects);
    return;
  }

  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (projectMatch && request.method === 'PATCH') {
    try {
      const body = await readJson(request);
      const projectId = Number(projectMatch[1]);
      const project = database.prepare('SELECT id, name, archived FROM projects WHERE id = ?').get(projectId);
      if (!project) {
        sendJson(response, 404, { error: 'Project not found' });
        return;
      }
      if (typeof body?.archived === 'boolean') {
        database.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(Number(body.archived), projectId);
        sendJson(response, 200, { id: projectId, archived: body.archived });
        return;
      }
      const name = typeof body?.name === 'string' ? body.name.trim() : '';
      if (!name) {
        sendJson(response, 400, { error: 'Project name is required' });
        return;
      }
      if (project.archived) {
        sendJson(response, 400, { error: 'Archived projects cannot be renamed' });
        return;
      }
      database.prepare('UPDATE projects SET name = ? WHERE id = ?').run(name, projectId);
      sendJson(response, 200, { id: projectId, name, archived: false });
    } catch {
      sendJson(response, 400, { error: 'Invalid request' });
    }
    return;
  }

  if (request.method === 'POST' && url.pathname === '/api/projects') {
    try {
      const body = await readJson(request);
      const name = typeof body?.name === 'string' ? body.name.trim() : '';
      if (!name) {
        sendJson(response, 400, { error: 'Project name is required' });
        return;
      }
      const result = database.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
      sendJson(response, 201, { id: Number(result.lastInsertRowid), name, archived: false, totalCount: 0, completedCount: 0 });
    } catch {
      sendJson(response, 400, { error: 'Invalid request' });
    }
    return;
  }

  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch && request.method === 'GET') {
    const projectId = Number(tasksMatch[1]);
    const project = database.prepare('SELECT id FROM projects WHERE id = ?').get(projectId);
    if (!project) {
      sendJson(response, 404, { error: 'Project not found' });
      return;
    }
    const tasks = database.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id').all(projectId)
      .map((task) => ({ ...task, id: Number(task.id), projectId: Number(task.projectId), completed: Boolean(task.completed) }));
    sendJson(response, 200, tasks);
    return;
  }

  if (tasksMatch && request.method === 'POST') {
    try {
      const projectId = Number(tasksMatch[1]);
      const project = database.prepare('SELECT id, archived FROM projects WHERE id = ?').get(projectId);
      if (!project) {
        sendJson(response, 404, { error: 'Project not found' });
        return;
      }
      if (project.archived) {
        sendJson(response, 400, { error: 'Archived projects cannot have new tasks' });
        return;
      }
      const body = await readJson(request);
      const title = typeof body?.title === 'string' ? body.title.trim() : '';
      if (!title) {
        sendJson(response, 400, { error: 'Task title is required' });
        return;
      }
      const result = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(projectId, title);
      sendJson(response, 201, { id: Number(result.lastInsertRowid), projectId, title, completed: false });
    } catch {
      sendJson(response, 400, { error: 'Invalid request' });
    }
    return;
  }

  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  if (taskMatch && request.method === 'PATCH') {
    try {
      const projectId = Number(taskMatch[1]);
      const taskId = Number(taskMatch[2]);
      const body = await readJson(request);
      if (typeof body?.completed !== 'boolean') {
        sendJson(response, 400, { error: 'Completion state is required' });
        return;
      }
      const result = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?').run(Number(body.completed), taskId, projectId);
      if (!Number(result.changes)) {
        sendJson(response, 404, { error: 'Task not found' });
        return;
      }
      sendJson(response, 200, { id: taskId, projectId, completed: body.completed });
    } catch {
      sendJson(response, 400, { error: 'Invalid request' });
    }
    return;
  }

  if (request.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+$/.test(url.pathname))) {
    response.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    response.end(indexHtml);
    return;
  }

  sendJson(response, 404, { error: 'Not found' });
});

server.listen(port, '0.0.0.0');

process.on('SIGINT', () => {
  server.close(() => {
    database.close();
    process.exit(0);
  });
});
process.on('SIGTERM', () => {
  server.close(() => {
    database.close();
    process.exit(0);
  });
});
<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Workboard</title>
    <style>
      :root { color-scheme: light; font-family: system-ui, sans-serif; color: #172033; background: #f5f7fb; }
      * { box-sizing: border-box; }
      body { margin: 0; }
      main { width: min(720px, calc(100% - 32px)); margin: 64px auto; }
      h1 { margin: 0 0 28px; font-size: 2rem; }
      .panel { padding: 24px; background: white; border: 1px solid #dce2eb; border-radius: 12px; box-shadow: 0 4px 16px #1720330b; }
      form { display: flex; gap: 12px; align-items: end; }
      label { display: grid; gap: 8px; flex: 1; font-weight: 600; }
      input { min-width: 0; padding: 11px 12px; border: 1px solid #aeb9c9; border-radius: 6px; font: inherit; }
      button { padding: 11px 16px; border: 0; border-radius: 6px; background: #2457c5; color: white; font: inherit; font-weight: 600; cursor: pointer; }
      button:hover { background: #1946a8; }
      button:focus-visible, input:focus-visible { outline: 3px solid #8eb3ff; outline-offset: 2px; }
      [role="alert"] { margin: 12px 0 0; color: #a32020; }
      ul { list-style: none; padding: 0; margin: 20px 0 0; }
      .project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 0; border-top: 1px solid #e3e7ee; }
      .project-name { overflow-wrap: anywhere; }
      .back-button { margin-bottom: 20px; background: #e8edf6; color: #172033; }
      .back-button:hover { background: #dce4f1; }
      .task-row { display: flex; align-items: center; gap: 12px; padding: 14px 0; border-top: 1px solid #e3e7ee; }
      .task-row label { display: flex; align-items: center; gap: 10px; font-weight: 400; }
      input[type="checkbox"] { width: 18px; height: 18px; }
      select { padding: 10px 12px; border: 1px solid #aeb9c9; border-radius: 6px; font: inherit; }
      @media (max-width: 520px) { main { margin-top: 32px; } form { align-items: stretch; flex-direction: column; } }
    </style>
  </head>
  <body>
    <main id="app" aria-live="polite"></main>
    <script type="module">
      const app = document.querySelector('#app');

      function element(tag, text, className) {
        const node = document.createElement(tag);
        if (text !== undefined) node.textContent = text;
        if (className) node.className = className;
        return node;
      }

      async function loadProjects() {
        const response = await fetch('/api/projects');
        if (!response.ok) throw new Error('Could not load projects');
        return response.json();
      }

      async function showList() {
        app.replaceChildren();
        app.append(element('h1', 'Workboard'));
        const panel = element('section', undefined, 'panel');
        const projectFilterLabel = element('label', 'Project filter');
        const projectFilter = document.createElement('select');
        for (const value of ['Active', 'Archived']) {
          const option = element('option', value);
          option.value = value;
          projectFilter.append(option);
        }
        projectFilterLabel.append(projectFilter);
        const form = document.createElement('form');
        const label = element('label', 'Project name');
        const input = document.createElement('input');
        input.type = 'text';
        input.name = 'projectName';
        input.autocomplete = 'off';
        label.append(input);
        const submit = element('button', 'Create project');
        submit.type = 'submit';
        form.append(label, submit);
        const alert = element('p', undefined);
        alert.setAttribute('role', 'alert');
        alert.hidden = true;
        const list = element('ul');
        panel.append(projectFilterLabel, form, alert, list);
        app.append(panel);

        form.addEventListener('submit', async (event) => {
          event.preventDefault();
          const name = input.value.trim();
          if (!name) {
            alert.textContent = 'Project name is required';
            alert.hidden = false;
            input.focus();
            return;
          }
          const response = await fetch('/api/projects', {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ name }),
          });
          if (!response.ok) {
            alert.textContent = 'Project name is required';
            alert.hidden = false;
            return;
          }
          const project = await response.json();
          alert.hidden = true;
          input.value = '';
          projects.push(project);
          renderProjects();
        });

        const projects = await loadProjects();
        function renderProjects() {
          list.replaceChildren();
          for (const project of projects.filter((item) => item.archived === (projectFilter.value === 'Archived'))) {
            appendProject(list, project, async () => {
              const response = await fetch(`/api/projects/${project.id}`, {
                method: 'PATCH', headers: { 'content-type': 'application/json' },
                body: JSON.stringify({ archived: !project.archived }),
              });
              if (!response.ok) return;
              project.archived = !project.archived;
              renderProjects();
            });
          }
        }
        projectFilter.addEventListener('change', renderProjects);
        renderProjects();
      }

      function appendProject(list, project, onArchive) {
        const row = element('li', undefined, 'project-row');
        row.dataset.testid = 'project-row';
        row.append(element('span', project.name, 'project-name'));
        const summary = element('span', `${project.completedCount}/${project.totalCount} completed`);
        summary.dataset.testid = 'project-summary';
        row.append(summary);
        const open = element('button', 'Open project');
        open.type = 'button';
        open.addEventListener('click', () => {
          history.pushState({}, '', `/projects/${project.id}`);
          showProject(project);
        });
        row.append(open);
        const archive = element('button', project.archived ? 'Restore project' : 'Archive project');
        archive.type = 'button';
        archive.addEventListener('click', onArchive);
        row.append(archive);
        list.append(row);
      }

      async function showProject(project) {
        app.replaceChildren();
        const back = element('button', 'Projects', 'back-button');
        back.type = 'button';
        back.addEventListener('click', () => {
          history.pushState({}, '', '/');
          showList();
        });
        const heading = element('h1', project.name);
        const panel = element('section', undefined, 'panel');
        if (project.archived) panel.append(element('p', 'Archived project'));
        const renameForm = document.createElement('form');
        const renameLabel = element('label', 'New project name');
        const renameInput = document.createElement('input');
        renameInput.type = 'text';
        renameInput.value = project.name;
        renameInput.disabled = project.archived;
        renameLabel.append(renameInput);
        const renameButton = element('button', 'Rename project');
        renameButton.type = 'submit';
        renameButton.disabled = project.archived;
        renameForm.append(renameLabel, renameButton);
        const renameAlert = element('p');
        renameAlert.setAttribute('role', 'alert');
        renameAlert.hidden = true;
        const form = document.createElement('form');
        const label = element('label', 'Task title');
        const input = document.createElement('input');
        input.type = 'text';
        input.name = 'taskTitle';
        input.autocomplete = 'off';
        label.append(input);
        const submit = element('button', 'Create task');
        submit.type = 'submit';
        submit.disabled = project.archived;
        form.append(label, submit);
        const alert = element('p');
        alert.setAttribute('role', 'alert');
        alert.hidden = true;
        const filterLabel = element('label', 'Task filter');
        const filter = document.createElement('select');
        for (const value of ['All', 'Open', 'Completed']) {
          const option = element('option', value);
          option.value = value;
          filter.append(option);
        }
        filterLabel.append(filter);
        const list = element('ul');
        panel.append(renameForm, renameAlert, form, alert, filterLabel, list);
        app.append(back, heading, panel);

        renameForm.addEventListener('submit', async (event) => {
          event.preventDefault();
          const name = renameInput.value.trim();
          if (!name) {
            renameAlert.textContent = 'Project name is required';
            renameAlert.hidden = false;
            renameInput.focus();
            return;
          }
          const response = await fetch(`/api/projects/${project.id}`, {
            method: 'PATCH',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ name }),
          });
          if (!response.ok) {
            renameAlert.textContent = 'Project name is required';
            renameAlert.hidden = false;
            return;
          }
          project.name = name;
          heading.textContent = name;
          renameInput.value = name;
          renameAlert.hidden = true;
        });

        let tasks = await loadTasks(project.id);
        function renderTasks() {
          list.replaceChildren();
          const matching = tasks.filter((task) => filter.value === 'All' || (filter.value === 'Completed') === task.completed);
          for (const task of matching) appendTask(list, task, project.id, project.archived, (updated) => {
            tasks = tasks.map((item) => item.id === updated.id ? updated : item);
            renderTasks();
          });
        }
        filter.addEventListener('change', renderTasks);
        form.addEventListener('submit', async (event) => {
          event.preventDefault();
          const title = input.value.trim();
          if (!title) {
            alert.textContent = 'Task title is required';
            alert.hidden = false;
            input.focus();
            return;
          }
          const response = await fetch(`/api/projects/${project.id}/tasks`, {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ title }),
          });
          if (!response.ok) {
            alert.textContent = 'Task title is required';
            alert.hidden = false;
            return;
          }
          tasks.push(await response.json());
          alert.hidden = true;
          input.value = '';
          renderTasks();
        });
        renderTasks();
      }

      async function loadTasks(projectId) {
        const response = await fetch(`/api/projects/${projectId}/tasks`);
        if (!response.ok) throw new Error('Could not load tasks');
        return response.json();
      }

      function appendTask(list, task, projectId, archived, onUpdate) {
        const row = element('li', undefined, 'task-row');
        row.dataset.testid = 'task-row';
        const label = document.createElement('label');
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = task.completed;
        checkbox.disabled = archived;
        checkbox.setAttribute('aria-label', `Complete ${task.title}`);
        checkbox.addEventListener('change', async () => {
          checkbox.disabled = true;
          const response = await fetch(`/api/projects/${projectId}/tasks/${task.id}`, {
            method: 'PATCH',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          if (response.ok) onUpdate({ ...task, completed: checkbox.checked });
          else checkbox.checked = task.completed;
          checkbox.disabled = false;
        });
        label.append(checkbox, element('span', task.title));
        row.append(label);
        list.append(row);
      }

      async function renderRoute() {
        const match = location.pathname.match(/^\/projects\/(\d+)$/);
        if (!match) return showList();
        const projects = await loadProjects();
        const project = projects.find((item) => String(item.id) === match[1]);
        if (project) return showProject(project);
        history.replaceState({}, '', '/');
        return showList();
      }

      addEventListener('popstate', renderRoute);
